            vertexLayout: VertexLayout,
            vertexCount: Int,
            vertexConsumer: Consumer<VertexConsumer>
        ) = compile(vertexLayout, vertexCount, vertexConsumer, false)

        @JvmStatic
        fun compilePersistent(
            vertexLayout: VertexLayout,
            vertexCount: Int,
            vertexConsumer: Consumer<VertexConsumer>
        ) = compile(vertexLayout, vertexCount, vertexConsumer, true)
    }

